-- FAKKIR seed — part 1 of 9. Generated; do not edit by hand.
-- Run server/sql/schema.sql once, then paste these part files into the Supabase SQL Editor in order (01, 02, ...).
begin;

-- ensure the per-question image column exists (players photos etc.)
alter table questions add column if not exists image text;

-- Replace all game content: versions A–O fully replace any previous data.
delete from questions;
delete from flags;

-- Categories (idempotent; required by the questions foreign key)
on conflict(slug) do update set name=excluded.name,color=excluded.color,image=excluded.image,sort_order=excluded.sort_order;

on conflict(key) do update set image=excluded.image;

-- Questions 1..250
on conflict(category,version,ord) do update set value=excluded.value,type=excluded.type,q=excluded.q,a=excluded.a,note=excluded.note,flag=excluded.flag,clues=excluded.clues,num=excluded.num,evidence=excluded.evidence,suspects=excluded.suspects,image=excluded.image;

commit;
